import{_ as d,o as e,c as o,a2 as r}from"./chunks/framework.BYgiQ6KE.js";const u=JSON.parse('{"title":"Angular 漫画剧场风格规范 · 霓虹墨 Neon Ink","description":"","frontmatter":{},"headers":[],"relativePath":"comics/style-guide.md","filePath":"comics/style-guide.md","lastUpdated":1793863170000}'),a={name:"comics/style-guide.md"};function c(i,t,n,l,s,g){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="angular-漫画剧场风格规范-·-霓虹墨-neon-ink" tabindex="-1">Angular 漫画剧场风格规范 · 霓虹墨 Neon Ink <a class="header-anchor" href="#angular-漫画剧场风格规范-·-霓虹墨-neon-ink" aria-label="Permalink to &quot;Angular 漫画剧场风格规范 · 霓虹墨 Neon Ink&quot;">​</a></h1><blockquote><p>本规范是 <code>docs/comics/</code> 全部漫画的唯一视觉与叙事标准。新增或修改任何一话，都必须对照本文档执行。</p></blockquote><h2 id="_1-画布与分格" tabindex="-1">1. 画布与分格 <a class="header-anchor" href="#_1-画布与分格" aria-label="Permalink to &quot;1. 画布与分格&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>规定</th></tr></thead><tbody><tr><td>画布</td><td><code>viewBox=&quot;0 0 1200 840&quot;</code>，深墨底渐变（左上 <code>#0b1220</code> → 右下 <code>#101a33</code>）</td></tr><tr><td>分格</td><td>2×2 四格，面板尺寸 <strong>572×361</strong>，圆角 14</td></tr><tr><td>面板坐标</td><td>左上 <code>(20,84)</code>、右上 <code>(608,84)</code>、左下 <code>(20,462)</code>、右下 <code>(608,462)</code></td></tr><tr><td>页眉</td><td>EP 徽章（<strong>Angular 红 <code>#DD0031</code></strong> 圆角矩形 92×36）+ 标题（渐变字 26px）+ 右侧系列名；页眉下 1160×2 渐变分隔线（y=62）</td></tr><tr><td>装饰</td><td>每格 1~2 条斜切光楔（多边形，霓虹色 opacity ≤0.05），禁止高不透明度大色块</td></tr></tbody></table><h2 id="_2-色板-60-30-10" tabindex="-1">2. 色板（60/30/10） <a class="header-anchor" href="#_2-色板-60-30-10" aria-label="Permalink to &quot;2. 色板（60/30/10）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>用途</th><th>色值</th></tr></thead><tbody><tr><td>底色（60%）</td><td><code>#0b1220</code> <code>#101a33</code> <code>#0e1730</code>（面板）</td></tr><tr><td>结构线/弱文本（30%）</td><td><code>#1e2a44</code> <code>#223055</code> <code>#64748b</code> <code>#94a3b8</code> <code>#e2e8f0</code></td></tr><tr><td>霓虹强调（10%）</td><td>Angular 红 <code>#DD0031</code> / 青 <code>#22d3ee</code> / 紫 <code>#a78bfa</code> / 品红 <code>#f472b6</code> / 橙 <code>#f97316</code> / 绿 <code>#34d399</code> / 黄 <code>#fbbf24</code></td></tr><tr><td>面板编号色</td><td>1=青、2=紫、3=品红、4=橙</td></tr><tr><td>标题渐变</td><td><code>#DD0031</code> → <code>#f472b6</code>（Angular 红到品红）</td></tr></tbody></table><p>对比度规则：气泡为浅底（<code>#f8fafc</code>）配深字（<code>#0b1220</code>）；深底上正文用 <code>#e2e8f0</code>；强调词单独 <code>&lt;tspan&gt;</code> 换霓虹色。所有文字对比度 ≥ 4.5:1。</p><h2 id="_3-字号阶梯与字体" tabindex="-1">3. 字号阶梯与字体 <a class="header-anchor" href="#_3-字号阶梯与字体" aria-label="Permalink to &quot;3. 字号阶梯与字体&quot;">​</a></h2><table tabindex="0"><thead><tr><th>元素</th><th>字号</th><th>字色</th></tr></thead><tbody><tr><td>话标题</td><td>26 bold</td><td>渐变（Angular 红→品红）</td></tr><tr><td>面板标题</td><td>17 bold</td><td><code>#e2e8f0</code></td></tr><tr><td>气泡正文</td><td>15~16</td><td><code>#0b1220</code>（浅底）</td></tr><tr><td>代码</td><td>12~13 mono</td><td><code>#7dd3fc</code> / <code>#fbbf24</code> / <code>#34d399</code></td></tr><tr><td>注脚/水印</td><td>11~12</td><td><code>#64748b</code></td></tr></tbody></table><ul><li><code>font-family=&quot;&#39;PingFang SC&#39;,&#39;Hiragino Sans GB&#39;,&#39;Microsoft YaHei&#39;,sans-serif&quot;</code>；代码用 <code>&#39;SF Mono&#39;,&#39;JetBrains Mono&#39;,Consolas,monospace</code>。</li><li><strong>每个 <code>&lt;text&gt;</code>/<code>&lt;tspan&gt;</code> 必须显式写 <code>font-size</code></strong>（校验脚本依赖）。</li><li>气泡单行 ≤ 17 个汉字（约 272px），代码单行 ≤ 40 字符。</li></ul><h2 id="_4-组件规范" tabindex="-1">4. 组件规范 <a class="header-anchor" href="#_4-组件规范" aria-label="Permalink to &quot;4. 组件规范&quot;">​</a></h2><ul><li><strong>气泡</strong>：圆角 10 浅底矩形 + 小三角尾巴指向说话人；尾巴必须连到头像。</li><li><strong>头像（半身 44px 级）</strong>：头圆 r≈17 + 发型 + 眼睛两点 + 微笑弧 + 身体圆角矩形。</li><li><strong>代码芯片</strong>：深底 <code>#0a0f1c</code>、描边霓虹色（opacity 0.35）、圆角 8、内边距 ≥12。</li><li><strong>坑点标签</strong>：橙 <code>#f97316</code> 小圆角条 + &quot;⚠ 坑点&quot; 前缀，只出现在第 4 格。</li><li><strong>转义</strong>：文本中 <code>&lt;</code> → <code>&amp;lt;</code>、<code>&gt;</code> → <code>&amp;gt;</code>、<code>&amp;</code> → <code>&amp;amp;</code>；禁止在属性值里出现 <code>&gt;</code>。</li></ul><h2 id="_5-三角色设定" tabindex="-1">5. 三角色设定 <a class="header-anchor" href="#_5-三角色设定" aria-label="Permalink to &quot;5. 三角色设定&quot;">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>人设</th><th>视觉锚点</th></tr></thead><tbody><tr><td><strong>标签君</strong></td><td>行动派，热情外向、爱动手试验模板与指令</td><td>橙色刺猬头 + 蓝外套 + <code>&lt;app-root&gt;</code> 徽章</td></tr><tr><td><strong>像素酱</strong></td><td>提问担当，对 Angular 机制好奇、一针见血</td><td>青色高马尾 + Angular 红卫衣 + <code>{signal}</code> 徽章</td></tr><tr><td><strong>码叔</strong></td><td>教授，沉稳专业、负责总结框架原理</td><td>白发白须 + 圆框眼镜 + 浅灰大褂 + 指教鞭</td></tr></tbody></table><p>叙事分工：标签君/像素酱负责&quot;提出问题、制造冲突&quot;，码叔负责&quot;揭示原理、给出最佳实践&quot;。每话至少两角色出场。</p><h2 id="_6-叙事结构-四幕" tabindex="-1">6. 叙事结构（四幕） <a class="header-anchor" href="#_6-叙事结构-四幕" aria-label="Permalink to &quot;6. 叙事结构（四幕）&quot;">​</a></h2><ol><li><strong>第一格 · 困境</strong>：真实开发场景抛出 Angular 问题（模板不刷新 / 注入器炸了 / 指令写错）；</li><li><strong>第二格 · 揭秘</strong>：原理拆解，配 1 段迷你 Angular 代码芯片；</li><li><strong>第三格 · 实证</strong>：经典示例或对比（正确 vs 错误 / 执行顺序图示 / 框架行为动画）；</li><li><strong>第四格 · 结案</strong>：最佳实践 + ⚠ 坑点标签 + 一句码叔总结。</li></ol><p>每格左上角有编号色块（1~4）+ 4~8 字面板标题；整话无对白超过 3 行/气泡。</p><h2 id="_7-命名与文件" tabindex="-1">7. 命名与文件 <a class="header-anchor" href="#_7-命名与文件" aria-label="Permalink to &quot;7. 命名与文件&quot;">​</a></h2><ul><li>一话 = <code>EP.NN-slug.svg</code> + <code>EP.NN-slug.md</code>，NN 两位数，slug 全小写连字符；</li><li>一话严格对应 <code>guide/</code> 下一章；</li><li>新增话必须同步：<code>manifest.json</code>、<code>README.md</code> 导航表。</li></ul><h2 id="_8-章节映射" tabindex="-1">8. 章节映射 <a class="header-anchor" href="#_8-章节映射" aria-label="Permalink to &quot;8. 章节映射&quot;">​</a></h2><table tabindex="0"><thead><tr><th>EP</th><th>主题</th><th>对应正文</th></tr></thead><tbody><tr><td>EP.01</td><td>standalone 登场与 signal 心跳</td><td><code>guide/part1/01-first-app</code></td></tr><tr><td>EP.02</td><td>模板里那些糖</td><td><code>guide/part1/02-template-syntax</code></td></tr><tr><td>EP.03</td><td>DI 那张透明网</td><td><code>guide/part2/03-di-service</code></td></tr><tr><td>EP.04</td><td>路由门卫与响应式表单</td><td><code>guide/part2/04-routing-form</code></td></tr><tr><td>EP.05</td><td>Signal 就是信号枪</td><td><code>guide/part3/05-signals</code></td></tr><tr><td>EP.06</td><td>RxJS 流过你的代码</td><td><code>guide/part3/06-http-rxjs</code></td></tr><tr><td>EP.07</td><td>懒加载怎么瘦体积</td><td><code>guide/part4/07-build</code></td></tr><tr><td>EP.08</td><td>把代码关进测试笼子</td><td><code>guide/part4/08-testing</code></td></tr><tr><td>EP.09</td><td>百万行也能丝滑</td><td><code>guide/part5/09-performance</code></td></tr><tr><td>EP.10</td><td>让所有人都能用</td><td><code>guide/part5/10-a11y-i18n</code></td></tr><tr><td>EP.11</td><td>大型应用怎么分层</td><td><code>guide/part6/11-architecture</code></td></tr><tr><td>EP.12</td><td>Angular 内部那点事</td><td><code>guide/part6/12-internals</code></td></tr><tr><td>EP.13</td><td>导航链上的三道门</td><td><code>guide/part7/13-routing-advanced</code></td></tr><tr><td>EP.14</td><td>表单的三件武器</td><td><code>guide/part7/14-forms-advanced</code></td></tr><tr><td>EP.15</td><td>信任边界</td><td><code>guide/part7/15-security</code></td></tr><tr><td>EP.16</td><td>服务端先画一遍</td><td><code>guide/part7/16-ssr-hydration</code></td></tr><tr><td>EP.17</td><td>模板编译两遍</td><td><code>guide/part7/17-compiler-ivy</code></td></tr><tr><td>EP.18</td><td>迁移不重写</td><td><code>guide/part7/18-migration-governance</code></td></tr></tbody></table>',22)])])}const b=d(a,[["render",c]]);export{u as __pageData,b as default};
